import Button from "@mui/material/Button";
import Stack from "@mui/material/Stack";


export default function QuackNet() {
  return (
    <Stack direction="row" spacing={2} sx= {{ justifyContent: "space-evenly", alignItems: "flex-start" }}>
      <img src={'/images/duck.png'} className="App-logo" alt="logo" />
      <Button variant="text">QuackNet</Button>
    </Stack>
  );
}
